props.vertexShader:
precision highp float;
in vec3 position;
uniform mat4 mvp;
void main() { gl_Position = mvp * vec4( position, 1.0 ); }

props.fragmentShader:
precision highp float;
out vec4 outputColor;
void main() { outputColor = vec4( 0.25, 0.5, 0.75, 1.0 ); }

#if __VERSION__ == 300 && defined( GL_ES )
#define FIXTURE_COLOR_SCALE 0.5
#else
#define FIXTURE_COLOR_SCALE 1.0
#endif
uniform float fixtureGain;
varying vec3 fixtureVarying;
void main() { gl_FragColor = vec4( abs( fixtureVarying ) * fixtureGain * FIXTURE_COLOR_SCALE, 1.0 ); }

props.vertexShader:
precision highp float;
#if defined( GL_ES ) && __VERSION__ == 300
#define FIXTURE_ENV_SCALE 1.0
#else
#define FIXTURE_ENV_SCALE 2.0
#endif
in vec3 position;
out vec3 fixtureVarying;
uniform mat4 fixtureTransform;
uniform float fixtureGain;
void main() { fixtureVarying = position; gl_Position = fixtureTransform * vec4( position * fixtureGain * FIXTURE_ENV_SCALE, 1.0 ); }

props.fragmentShader:
precision highp float;
#if __VERSION__ == 300
#define FIXTURE_VERSION_SCALE 0.3
#else
#define FIXTURE_VERSION_SCALE 0.9
#endif
#ifdef GL_ES
#define FIXTURE_COLOR_SCALE 0.5
#else
#define FIXTURE_COLOR_SCALE 1.0
#endif
in vec3 fixtureVarying;
uniform float fixtureGain;
out vec4 fixtureOutput;
void main() { fixtureOutput = vec4( abs( fixtureVarying ) * fixtureGain * FIXTURE_COLOR_SCALE * FIXTURE_VERSION_SCALE, 1.0 ); }
